?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SmartToolz Background Remover</title><meta name="description" content="Remove image backgrounds quickly in your browser with SmartToolz."><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Material+Symbols+Rounded:opsz,wght,FILL,GRAD@20..48,500,0,0&display=swap" rel="stylesheet"><style>:root{--p:#635bff;--ink:#171a24;--muted:#7a8191;--line:#e6e8ee;--bg:#f7f8fc}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,system-ui,sans-serif}.material-symbols-rounded{font-size:20px;line-height:1}.page{width:min(760px,calc(100% - 24px));margin:0 auto;padding:28px 0 36px}.intro{text-align:center;margin-bottom:16px}.intro h1{margin:0;font-size:clamp(26px,4vw,38px);letter-spacing:-1.5px}.intro h1 span{color:var(--p)}.intro p{margin:7px 0 0;color:var(--muted);font-size:10px}.tool{background:#fff;border:1px solid var(--line);border-radius:18px;overflow:hidden;box-shadow:0 14px 40px rgba(23,26,36,.06)}.bar{height:46px;padding:0 12px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}.state{display:flex;align-items:center;gap:8px;font-size:8px;font-weight:800}.state i{width:7px;height:7px;border-radius:50%;background:#22c55e;box-shadow:0 0 0 4px #dcfce7}.bar button{border:1px solid var(--line);background:#fff;border-radius:8px;padding:7px 9px;font-size:8px;font-weight:800;color:#555d6d;cursor:pointer}.area{padding:12px}.drop{min-height:300px;border:1px dashed #cfd4de;border-radius:14px;display:grid;place-items:center;text-align:center;padding:20px;background:#fafbfe;transition:.2s}.drop.drag{border-color:var(--p);background:#f7f6ff}.drop h2{margin:9px 0 5px;font-size:19px;letter-spacing:-.4px}.drop p{margin:0 auto 14px;max-width:360px;color:var(--muted);font-size:9px;line-height:1.6}.upload{width:52px;height:52px;margin:auto;border-radius:14px;display:grid;place-items:center;background:#eeecff;color:var(--p)}.choose{display:inline-flex;align-items:center;gap:7px;padding:11px 16px;border-radius:10px;background:var(--p);color:#fff;font-size:9px;font-weight:800;cursor:pointer}.meta{margin-top:9px;color:#a0a6b2;font-size:7px}.viewer{display:none;position:relative;min-height:220px;align-items:center;justify-content:center;padding:12px;border-radius:14px;background:repeating-conic-gradient(#eef1f5 0 25%,#fafbfc 0 50%) 50%/20px 20px;overflow:hidden}.viewer img{display:block;max-width:100%;max-height:360px;object-fit:contain;border-radius:10px;box-shadow:0 12px 30px rgba(18,22,34,.12)}.magic{position:absolute;inset:0;display:none;align-items:center;justify-content:center;pointer-events:none;background:radial-gradient(circle at center,rgba(99,91,255,.09),transparent 48%)}.magic-line{position:absolute;left:8%;right:8%;height:2px;background:linear-gradient(90deg,transparent,#756dff 25%,#fff 50%,#756dff 75%,transparent);box-shadow:0 0 22px rgba(99,91,255,.65);animation:magic 1.8s ease-in-out infinite}.magic-ring{width:110px;height:110px;border:1px solid rgba(99,91,255,.3);border-radius:50%;box-shadow:0 0 0 8px rgba(99,91,255,.04),0 0 28px rgba(99,91,255,.18);animation:ring 1.8s ease-in-out infinite}.processing .magic{display:flex}.processing img{filter:saturate(.9) brightness(1.03)}@keyframes magic{0%{top:10%;opacity:0}18%{opacity:1}50%{top:50%;opacity:1}82%{opacity:1}100%{top:90%;opacity:0}}@keyframes ring{0%,100%{transform:scale(.78);opacity:.35}50%{transform:scale(1.12);opacity:.9}}.progress{position:absolute;left:12px;right:12px;bottom:12px;padding:10px 11px;border-radius:11px;background:rgba(20,23,31,.9);color:#fff;backdrop-filter:blur(8px)}.prow{display:flex;justify-content:space-between;font-size:7px;font-weight:800}.track{height:4px;margin-top:7px;border-radius:99px;background:#323642;overflow:hidden}.track i{display:block;width:0;height:100%;background:linear-gradient(90deg,var(--p),#9b92ff);transition:width .18s ease}.actions{display:none;gap:8px;padding-top:10px}.actions button{flex:1;border:1px solid var(--line);background:#fff;border-radius:9px;padding:10px;font-size:9px;font-weight:800;cursor:pointer;color:#555d6d}.actions .primary{background:#171923;border-color:#171923;color:#fff}.guide{text-align:center;margin-top:10px}.guide a{color:#5a52d9;font-size:8px;font-weight:800;text-decoration:none}@media(max-width:600px){.page{width:calc(100% - 14px);padding-top:16px}.intro{margin-bottom:12px}.intro h1{font-size:26px}.drop{min-height:250px}.viewer{min-height:200px}.viewer img{max-height:300px}.actions{flex-direction:column}}</style></head><body><?php require_once __DIR__.'/../header.php'; ?><main class="page"><div class="intro"><h1>Background <span>Remover</span></h1><p>Remove the background from any image in your browser.</p></div><section class="tool"><div class="bar"><div class="state"><i></i><span id="status">Ready</span></div><button id="new" type="button">New image</button></div><div class="area"><div class="drop" id="drop"><div><div class="upload"><span class="material-symbols-rounded">content_cut</span></div><h2>Drop an image here</h2><p>Choose a photo and SmartToolz will remove the background automatically.</p><label class="choose"><span class="material-symbols-rounded">upload_file</span> Choose image<input id="picker" hidden type="file" accept="image/png,image/jpeg,image/webp"></label><div class="meta">PNG • JPG • WebP</div></div></div><div class="viewer" id="viewer"><img id="preview" alt="Image preview"><div class="magic"><div class="magic-ring"></div><div class="magic-line"></div></div><div class="progress" id="progress"><div class="prow"><span>Removing background…</span><span id="pct">0%</span></div><div class="track"><i id="fill"></i></div></div></div><div class="actions" id="actions"><button id="again" type="button">Try another</button><button id="download" class="primary" type="button">Download PNG</button></div></div></section><div class="guide"><a href="/knowledge-base/image-background-remover/article/">How to use this tool</a></div></main><script type="module">import{removeBackground}from'https://cdn.jsdelivr.net/npm/@imgly/background-removal@1.7.0/+esm';const $=id=>document.getElementById(id),picker=$('picker'),drop=$('drop'),viewer=$('viewer'),preview=$('preview'),progress=$('progress'),fill=$('fill'),pct=$('pct'),status=$('status'),actions=$('actions');let outUrl='',sourceUrl='';function reset(){picker.value='';drop.style.display='grid';viewer.style.display='none';viewer.classList.remove('processing');actions.style.display='none';status.textContent='Ready';if(outUrl)URL.revokeObjectURL(outUrl);if(sourceUrl)URL.revokeObjectURL(sourceUrl);outUrl='';sourceUrl=''}async function process(file){if(!file||!/^image\/(png|jpeg|webp)$/.test(file.type))return;drop.style.display='none';viewer.style.display='flex';viewer.classList.add('processing');actions.style.display='none';progress.style.display='block';fill.style.width='4%';pct.textContent='4%';status.textContent='Removing background';sourceUrl=URL.createObjectURL(file);preview.src=sourceUrl;try{const blob=await removeBackground(file,{model:'small',output:{format:'image/png',quality:1},progress:(name,current,total)=>{const p=total?Math.max(5,Math.min(96,Math.round(current/total*91)+5)):8;fill.style.width=p+'%';pct.textContent=p+'%'}});outUrl=URL.createObjectURL(blob);preview.src=outUrl;fill.style.width='100%';pct.textContent='100%';setTimeout(()=>{progress.style.display='none';viewer.classList.remove('processing');actions.style.display='flex';status.textContent='Done'},160)}catch(err){console.error(err);reset();status.textContent='Could not process image'}}picker.onchange=()=>{const f=picker.files?.[0];picker.value='';process(f)};drop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('drag')});drop.addEventListener('dragleave',()=>drop.classList.remove('drag'));drop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('drag');process(e.dataTransfer.files?.[0])});$('new').onclick=reset;$('again').onclick=reset;$('download').onclick=()=>{if(!outUrl)return;const a=document.createElement('a');a.href=outUrl;a.download='smarttoolz-background-removed.png';document.body.appendChild(a);a.click();a.remove()};window.addEventListener('beforeunload',()=>{if(outUrl)URL.revokeObjectURL(outUrl);if(sourceUrl)URL.revokeObjectURL(sourceUrl)});</script></body></html>